"""Frozen existing-profile bytes; normalize only the physical checkout location.

Amended for 7b84ea5a9's approved created-active-execution presentation capture:
only four screenshot artifact markers and their derived record hashes changed.
"""
import base64
import dataclasses
import zlib

from Scripts.reconstruction_gate_f.canonical_json import canonical_bytes, canonical_sha256, to_primitive
from Scripts.reconstruction_gate_f.command_compiler import compile_command_plan
from Scripts.reconstruction_gate_f.receipt_validator import CommandPrerequisiteExpectation, QualificationRunAuthority
from Scripts.reconstruction_gate_f.runtime_resolution import resolve_command_record
from Scripts.reconstruction_gate_f.scenario_compiler import compile_scenario_catalog
from Scripts.reconstruction_gate_f.tests import candidate_mapping
from Scripts.reconstruction_gate_f.schema import parse_candidate_identity
from Scripts.reconstruction_gate_f.tests.test_command_compiler import ROOT, command_inputs


def existing_snapshot(**profile):
    snapshots = []
    for commit in ("1" * 40, "e" * 40):
        mapping = candidate_mapping()
        mapping["source"]["commit"] = commit
        candidate, issues = parse_candidate_identity(mapping)
        assert not issues
        plan = compile_command_plan(candidate, compile_scenario_catalog(candidate),
                                    repository_root=ROOT, inputs=command_inputs(), **profile)
        normalized_plan = canonical_bytes(plan).replace(str(ROOT).encode(), b"/fixture/repository")
        resolutions = []
        for record in plan.commands:
            def normalize(value):
                return value.replace(str(ROOT), "/fixture/repository")
            normalized = dataclasses.replace(record, argv=tuple(map(normalize, record.argv)),
                working_directory=normalize(record.working_directory),
                environment=tuple((key, normalize(value)) for key, value in record.environment),
                generated_artifacts=tuple(map(normalize, record.generated_artifacts)),
                generated_logs=tuple(map(normalize, record.generated_logs)))
            predecessors = tuple(CommandPrerequisiteExpectation(command_id, "receipt-" + str(index),
                canonical_sha256({"command_id": command_id}), "fixture-run", "a" * 64)
                for index, command_id in enumerate(record.prerequisite_ids)
                if command_id != "candidate-identity-accepted")
            resolutions.append(to_primitive(resolve_command_record(normalized,
                prerequisite_receipts=predecessors,
                qualification_run=QualificationRunAuthority("fixture-run", "a" * 64), **profile)))
        snapshots.append({"plan_bytes": normalized_plan.decode(), "runtime": resolutions})
    return canonical_bytes(snapshots)


PRE_CHANGE_BYTES = ""


def frozen_snapshot():
    return zlib.decompress(base64.b64decode(PRE_CHANGE_BYTES))
